export class PartsWarehouseComponent implements OnInit {
  private readonly fb = inject(FormBuilder);
  private readonly notificationService = inject(NotificationService);
  private readonly storageKey = 'control-stock-parts-warehouse';

  items: SpareItem[] = [];
  oil: OilBarrelState = {
    capacityLiters: 1000,
    currentLiters: 1000,
  };

  readonly spareForm = this.fb.nonNullable.group({
    name: ['', Validators.required],
    category: ['FOCOS' as SpareCategory, Validators.required],
    stock: [0, [Validators.required, Validators.min(0)]],
  });

  readonly oilForm = this.fb.nonNullable.group({
    liters: [100, [Validators.required, Validators.min(1)]],
  });

  get oilPercentage(): number {
    return Math.max(0, Math.min(100, (this.oil.currentLiters / this.oil.capacityLiters) * 100));
  }

  get focos(): SpareItem[] {
    return this.items.filter((item) => item.category === 'FOCOS');
  }

  get ferreteria(): SpareItem[] {
    return this.items.filter((item) => item.category === 'FERRETERIA');
  }

  ngOnInit(): void {
    this.loadState();
  }

  createSpare(): void {
    if (this.spareForm.invalid) {
      this.spareForm.markAllAsTouched();
      return;
    }

    const raw = this.spareForm.getRawValue();
    const item: SpareItem = {
      id: this.createId(),
      name: raw.name.trim(),
      category: raw.category,
      stock: Number(raw.stock) || 0,
      createdAt: new Date().toISOString(),
    };

    this.items = [item, ...this.items];
    this.persistState();
    this.resetSpareForm();
    this.notificationService.show('success', 'Repuesto agregado al almacen.');
  }

  resetSpareForm(): void {
    this.spareForm.reset({
      name: '',
      category: 'FOCOS',
      stock: 0,
    });
  }

  changeStock(itemId: string, delta: number): void {
    this.items = this.items.map((item) => {
      if (item.id !== itemId) {
        return item;
      }

      return {
        ...item,
        stock: Math.max(0, item.stock + delta),
      };
    });

    this.persistState();
  }

  addOil(): void {
    const liters = Number(this.oilForm.getRawValue().liters) || 0;
    if (liters <= 0) {
      this.notificationService.show('error', 'Ingresa una cantidad valida de litros.');
      return;
    }

    this.oil.currentLiters = Math.min(this.oil.capacityLiters, this.oil.currentLiters + liters);
    this.persistState();
    this.notificationService.show('success', 'Aceite cargado en el barril.');
  }

  consumeOil(): void {
    const liters = Number(this.oilForm.getRawValue().liters) || 0;
    if (liters <= 0) {
      this.notificationService.show('error', 'Ingresa una cantidad valida de litros.');
      return;
    }

    if (liters > this.oil.currentLiters) {
      this.notificationService.show('error', 'No puedes descontar mas aceite del disponible.');
      return;
    }

    this.oil.currentLiters -= liters;
    this.persistState();
    this.notificationService.show('success', 'Consumo de aceite registrado.');
  }

  private loadState(): void {
    const saved = window.localStorage.getItem(this.storageKey);

    if (!saved) {
      this.persistState();
      return;
    }

    try {
      const state = JSON.parse(saved) as WarehouseState;
      this.items = Array.isArray(state.items) ? state.items : [];
      this.oil = state.oil?.capacityLiters
        ? {
            capacityLiters: state.oil.capacityLiters,
            currentLiters: state.oil.currentLiters,
          }
        : this.oil;
    } catch {
      this.persistState();
    }
  }

  private persistState(): void {
    const state: WarehouseState = {
      oil: this.oil,
      items: this.items,
    };

    window.localStorage.setItem(this.storageKey, JSON.stringify(state));
  }

  private createId(): string {
    return `spare-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  }
}
